import{_ as o,a0 as l,w as n,s as c,ao as r,I as a,x as s,a1 as t,A as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何使用特殊权限：setuid、setgid 和 sticky 位 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用特殊权限：setuid、setgid 和 sticky 位 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用特殊权限：setuid、setgid 和 sticky 位 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用特殊权限：setuid、setgid 和 sticky 位 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20171120 How to use special permissions- the setuid, setgid and sticky bits","title":"如何使用特殊权限：setuid、setgid 和 sticky 位","tag":"201802","desc":""},"relativePath":"201802/20171120 How to use special permissions- the setuid, setgid and sticky bits.md","filePath":"[post].md"}'),p={name:"201802/20171120 How to use special permissions- the setuid, setgid and sticky bits.md"};function h(g,e,u,k,b,f){const i=l("Link");return n(),c("div",null,[e[13]||(e[13]=r(`<h1 id="如何使用特殊权限-setuid、setgid-和-sticky-位" tabindex="-1">如何使用特殊权限：setuid、setgid 和 sticky 位 <a class="header-anchor" href="#如何使用特殊权限-setuid、setgid-和-sticky-位" aria-label="Permalink to “如何使用特殊权限：setuid、setgid 和 sticky 位”">​</a></h1><h3 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to “目标”">​</a></h3><p>了解特殊权限的工作原理，以及如何识别和设置它们。</p><h3 id="要求" tabindex="-1">要求 <a class="header-anchor" href="#要求" aria-label="Permalink to “要求”">​</a></h3><ul><li>了解标准的 Unix / Linux 权限系统</li></ul><h3 id="难度" tabindex="-1">难度 <a class="header-anchor" href="#难度" aria-label="Permalink to “难度”">​</a></h3><p>简单</p><h3 id="约定" tabindex="-1">约定 <a class="header-anchor" href="#约定" aria-label="Permalink to “约定”">​</a></h3><ul><li><code>#</code> - 要求直接以 root 用户或使用 <code>sudo</code> 命令执行指定的命令</li><li><code>$</code> - 用普通的非特权用户来执行指定的命令</li></ul><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h3><p>通常，在类 Unix 操作系统上，文件和目录的所有权是基于文件创建者的默认 <code>uid</code>（user-id）和 <code>gid</code>（group-id）的。启动一个进程时也是同样的情况：它以启动它的用户的 <code>uid</code> 和 <code>gid</code> 运行，并具有相应的权限。这种行为可以通过使用特殊的权限进行改变。</p><h3 id="setuid-位" tabindex="-1">setuid 位 <a class="header-anchor" href="#setuid-位" aria-label="Permalink to “setuid 位”">​</a></h3><p>当使用 setuid （设置用户 ID）位时，之前描述的行为会有所变化，所以当一个可执行文件启动时，它不会以启动它的用户的权限运行，而是<strong>以该文件所有者的权限运行</strong>。所以，如果在一个可执行文件上设置了 setuid 位，并且该文件由 root 拥有，当一个普通用户启动它时，它将以 root 权限运行。显然，如果 setuid 位使用不当的话，会带来潜在的安全风险。</p><p>使用 setuid 权限的可执行文件的例子是 <code>passwd</code>，我们可以使用该程序更改登录密码。我们可以通过使用 <code>ls</code> 命令来验证：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -l /bin/passwd</span></span>
<span class="line"><span>-rwsr-xr-x. 1 root root 27768 Feb 11 2017 /bin/passwd</span></span></code></pre></div><p>如何识别 <code>setuid</code> 位呢？相信您在上面命令的输出已经注意到，<code>setuid</code> 位是用 <code>s</code> 来表示的，代替了可执行位的 <code>x</code>。小写的 <code>s</code> 意味着可执行位已经被设置，否则你会看到一个大写的 <code>S</code>。大写的 <code>S</code> 发生于当设置了 <code>setuid</code> 或 <code>setgid</code> 位、但没有设置可执行位 <code>x</code> 时。它用于提醒用户这个矛盾的设置：如果可执行位未设置，则 <code>setuid</code> 和 <code>setgid</code> 位均不起作用。setuid 位对目录没有影响。</p><h3 id="setgid-位" tabindex="-1">setgid 位 <a class="header-anchor" href="#setgid-位" aria-label="Permalink to “setgid 位”">​</a></h3><p>与 <code>setuid</code> 位不同，<code>setgid</code> （设置组 ID）位对文件和目录都有影响。在第一个例子中，具有 <code>setgid</code> 位设置的文件在执行时，不是以启动它的用户所属组的权限运行，而是<strong>以拥有该文件的组运行</strong>。换句话说，进程的 <code>gid</code> 与文件的 <code>gid</code> 相同。</p><p>当在一个目录上使用时，<code>setgid</code> 位与一般的行为不同，它使得在所述目录内创建的文件，不属于创建者所属的组，而是属于父目录所属的组。这个功能通常用于文件共享（目录所属组中的所有用户都可以修改文件）。就像 setuid 一样，setgid 位很容易识别（我们用 test 目录举例）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -ld test</span></span>
<span class="line"><span>drwxrwsr-x. 2 egdoc egdoc 4096 Nov 1 17:25 test</span></span></code></pre></div><p>这次 <code>s</code> 出现在组权限的可执行位上。</p><h3 id="sticky-位" tabindex="-1">sticky 位 <a class="header-anchor" href="#sticky-位" aria-label="Permalink to “sticky 位”">​</a></h3><p>sticky （粘连）位的工作方式有所不同：它对文件没有影响，但当它在目录上使用时，所述目录中的所有文件只能由其所有者删除或移动。一个典型的例子是 <code>/tmp</code> 目录，通常系统中的所有用户都对这个目录有写权限。所以，设置 sticky 位使用户不能删除其他用户的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -ld /tmp</span></span>
<span class="line"><span>drwxrwxrwt. 14 root root 300 Nov 1 16:48 /tmp</span></span></code></pre></div><p>在上面的例子中，目录所有者、组和其他用户对该目录具有完全的权限（读、写和执行）。sticky 位在可执行位上用 <code>t</code> 来标识。同样，小写的 <code>t</code> 表示可执行权限 <code>x</code>也被设置了，否则你会看到一个大写字母 <code>T</code>。</p><h3 id="如何设置特殊权限位" tabindex="-1">如何设置特殊权限位 <a class="header-anchor" href="#如何设置特殊权限位" aria-label="Permalink to “如何设置特殊权限位”">​</a></h3><p>就像普通的权限一样，特殊权限位可以用 <code>chmod</code> 命令设置，使用数字或者 <code>ugo/rwx</code> 格式。在前一种情况下，<code>setuid</code>、<code>setgid</code> 和 <code>sticky</code> 位分别由数值 4、2 和 1 表示。例如，如果我们要在目录上设置 <code>setgid</code> 位，我们可以运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod 2775 test</span></span></code></pre></div><p>通过这个命令，我们在目录上设置了 <code>setgid</code> 位（由四个数字中的第一个数字标识），并给它的所有者和该目录所属组的所有用户赋予全部权限，对其他用户赋予读和执行的权限（目录上的执行位意味着用户可以 <code>cd</code> 进入该目录或使用 <code>ls</code> 列出其内容）。</p><p>另一种设置特殊权限位的方法是使用 <code>ugo/rwx</code> 语法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod g+s test</span></span></code></pre></div><p>要将 <code>setuid</code> 位应用于一个文件，我们可以运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod u+s file</span></span></code></pre></div><p>要设置 sticky 位，可运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod o+t test</span></span></code></pre></div><p>在某些情况下，使用特殊权限会非常有用。但如果使用不当，可能会引入严重的漏洞，因此使用之前请三思。</p><hr>`,37)),a("p",null,[e[1]||(e[1]=s("via: ",-1)),t(i,{href:"https://linuxconfig.org/how-to-use-special-permissions-the-setuid-setgid-and-sticky-bits"},{default:d(()=>[...e[0]||(e[0]=[s("https://linuxconfig.org/how-to-use-special-permissions-the-setuid-setgid-and-sticky-bits",-1)])]),_:1})]),a("p",null,[e[5]||(e[5]=s("作者：",-1)),t(i,{href:"https://linuxconfig.org"},{default:d(()=>[...e[2]||(e[2]=[s("Egidio Docile",-1)])]),_:1}),e[6]||(e[6]=s(" 译者：",-1)),t(i,{href:"https://github.com/jessie-pang"},{default:d(()=>[...e[3]||(e[3]=[s("jessie-pang",-1)])]),_:1}),e[7]||(e[7]=s(" 校对：",-1)),t(i,{href:"https://github.com/wxy"},{default:d(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1})]),a("p",null,[e[10]||(e[10]=s("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...e[8]||(e[8]=[s("LCTT",-1)])]),_:1}),e[11]||(e[11]=s(" 原创编译，",-1)),t(i,{href:"https://linux.cn/"},{default:d(()=>[...e[9]||(e[9]=[s("Linux中国",-1)])]),_:1}),e[12]||(e[12]=s(" 荣誉推出",-1))])])}const C=o(p,[["render",h]]);export{y as __pageData,C as default};
